import { summarizePrimitive } from "./trace-format.js";
import {
  appendTrace,
  traceIsEnabled,
} from "./trace-state.js";

export function traceCall(api, receiverName, argumentValues, resultValue) {
  if (!traceIsEnabled()) {
    return;
  }
  const argumentsSummary = new Array(argumentValues.length);
  for (let index = 0; index < argumentValues.length; index += 1) {
    argumentsSummary[index] = summarizePrimitive(argumentValues[index]);
  }
  appendTrace(
    "call",
    api,
    receiverName,
    argumentsSummary,
    summarizePrimitive(resultValue),
  );
}

export function traceConstruct(api, argumentValues, resultName) {
  if (!traceIsEnabled()) {
    return;
  }
  const argumentsSummary = new Array(argumentValues.length);
  for (let index = 0; index < argumentValues.length; index += 1) {
    argumentsSummary[index] = summarizePrimitive(argumentValues[index]);
  }
  appendTrace("construct", api, api, argumentsSummary, resultName);
}

export function summarizePrimitive(value) {
  if (
    value === undefined
    || value === null
    || typeof value === "boolean"
    || typeof value === "number"
    || typeof value === "bigint"
  ) {
    return value;
  }
  if (typeof value === "string") {
    return value.length <= 256 ? value : `${value.slice(0, 256)}…`;
  }
  if (typeof value === "symbol") {
    return "symbol";
  }
  if (typeof value === "function") {
    return "function";
  }
  return "object";
}

const traceState = {
  enabled: false,
  maxEntries: 100_000,
  nextSequence: 1,
  entries: [],
  startIndex: 0,
  size: 0,
};

export function configureTrace(enabled, maxEntries) {
  traceState.enabled = Boolean(enabled);
  if (Number.isSafeInteger(maxEntries) && maxEntries > 0) {
    traceState.maxEntries = maxEntries;
  }
  clearTrace();
}

export function enableTrace() {
  traceState.enabled = true;
}

export function disableTrace() {
  traceState.enabled = false;
}

export function clearTrace() {
  traceState.entries.length = 0;
  traceState.startIndex = 0;
  traceState.size = 0;
  traceState.nextSequence = 1;
}

export function traceIsEnabled() {
  return traceState.enabled;
}

export function appendTrace(operation, api, receiver, argumentsSummary, result) {
  if (!traceState.enabled) {
    return;
  }
  const entry = {
    sequence: traceState.nextSequence,
    operation,
    api,
    receiver,
    arguments: argumentsSummary,
    result,
  };
  traceState.nextSequence += 1;
  if (traceState.size < traceState.maxEntries) {
    traceState.entries.push(entry);
    traceState.size += 1;
    return;
  }
  traceState.entries[traceState.startIndex] = entry;
  traceState.startIndex = (
    traceState.startIndex + 1
  ) % traceState.maxEntries;
}

export function readTrace() {
  if (
    traceState.size < traceState.maxEntries
    || traceState.startIndex === 0
  ) {
    return traceState.entries.slice(0, traceState.size);
  }
  return [
    ...traceState.entries.slice(traceState.startIndex),
    ...traceState.entries.slice(0, traceState.startIndex),
  ];
}

