const nativeDateNow = Date.now.bind(Date);
const defaultTimingProfile = Object.freeze({
  timeOriginMs: nativeDateNow(),
  wallClockOffsetMs: 0,
  dateNowResolutionMs: 0,
  performanceResolutionMs: 0,
  performanceJitterMs: 0,
  jitterSeed: 0x4e5638,
  minimumTimerDelayMs: 0,
  animationFrameIntervalMs: 16,
});

let profile = defaultTimingProfile;
let sessionTimeOrigin = defaultTimingProfile.timeOriginMs;
let lastTimestamp = 0;
let lastWallClock = sessionTimeOrigin;
let jitterState = defaultTimingProfile.jitterSeed >>> 0;

export function configureTimingProfile(input = null) {
  const selected = input ?? defaultTimingProfile;
  profile = Object.freeze({
    ...defaultTimingProfile,
    ...selected,
    timeOriginMs: Number.isFinite(selected.timeOriginMs)
      ? selected.timeOriginMs
      : defaultTimingProfile.timeOriginMs,
  });
  sessionTimeOrigin = profile.timeOriginMs + profile.wallClockOffsetMs;
  lastTimestamp = 0;
  lastWallClock = Math.trunc(sessionTimeOrigin);
  jitterState = profile.jitterSeed >>> 0;
  if (jitterState === 0) jitterState = 0x6d2b79f5;
}

export function timingProfile() {
  return profile;
}

export function timeOrigin() {
  return sessionTimeOrigin;
}

export function wallClockNow() {
  const raw = nativeDateNow() + profile.wallClockOffsetMs;
  const resolution = profile.dateNowResolutionMs;
  const quantized = resolution > 0
    ? Math.floor(raw / resolution) * resolution
    : raw;
  const value = Math.trunc(quantized);
  if (value < lastWallClock) return lastWallClock;
  lastWallClock = value;
  return value;
}

export function monotonicNow() {
  const elapsed = Math.max(
    0,
    nativeDateNow() + profile.wallClockOffsetMs - sessionTimeOrigin,
  );
  const resolution = profile.performanceResolutionMs;
  let value = resolution > 0
    ? Math.floor(elapsed / resolution) * resolution
    : elapsed;
  if (profile.performanceJitterMs > 0) {
    value += nextJitter(profile.performanceJitterMs);
  }
  value = Math.max(lastTimestamp, value, 0);
  lastTimestamp = value;
  return value;
}

function nextJitter(amplitude) {
  jitterState = Math.imul(jitterState ^ (jitterState >>> 15), 1 | jitterState);
  jitterState ^= jitterState + Math.imul(jitterState ^ (jitterState >>> 7), 61 | jitterState);
  const normalized = ((jitterState ^ (jitterState >>> 14)) >>> 0) / 0xffffffff;
  return (normalized * 2 - 1) * amplitude;
}

