    case "port":
      return withPort(record, input);
    case "pathname":
      return {
        ...record,
        pathname: normalizePath(input.startsWith("/") ? input : `/${input}`),
      };
    case "search":
      return {
        ...record,
        search: input === "" ? "" : `?${input.replace(/^\?/u, "")}`,
