const state = new WeakMap();

const lengthUnits = new Map([
  [0, ["", 1]],
  [1, ["", 1]],
  [2, ["%", 1]],
  [3, ["em", 16]],
  [4, ["ex", 8]],
  [5, ["px", 1]],
  [6, ["cm", 96 / 2.54]],
  [7, ["mm", 96 / 25.4]],
  [8, ["in", 96]],
  [9, ["pt", 96 / 72]],
  [10, ["pc", 16]],
