    throw new TypeError("GPUUncapturedErrorEvent requires an event init object");
  }
  initializeEvent(this, `${type}`, {
    bubbles: Boolean(init.bubbles),
    cancelable: Boolean(init.cancelable),
    composed: Boolean(init.composed),
  });
