  } else if (name === "HKDF" && state.algorithm.name === "HKDF") {
    const hash = algorithmName(algorithm.hash);
    output = hkdf(
      state.bytes,
      bytesOf(algorithm.salt),
      bytesOf(algorithm.info),
      bitLength / 8,
      hash,
    );
  } else {
    unsupported();
  }
  return toArrayBuffer(output);
}

export async function subtleDeriveKey(
  subtle,
  algorithm,
  baseKey,
  derivedKeyType,
  extractable,
  keyUsages,
