  if (record.terminated) return;
  const cloned = performStructuredCloneDetailed(message);
  Promise.resolve().then(() => {
    if (record.terminated) return;
    const event = new MessageEvent("message", {
      data: cloned.value,
      ports,
    });
    record.worker.dispatchEvent(event);
