  if (value === undefined) return undefined;
  if (Array.isArray(value)) return { transfer: value };
  return value;
}

function requireWorker(value) {
  const record = workerState.get(value);
  if (record === undefined) throw new TypeError("Illegal invocation");
  return record;
}

