const state = new WeakMap();

export function DOMParser() {
  requireNew(new.target, "DOMParser");
  state.set(this, { kind: "parser" });
}
export function XMLSerializer() {
  requireNew(new.target, "XMLSerializer");
  state.set(this, { kind: "serializer" });
}
