  if (init === null || typeof init !== "object") {
    throw new TypeError("Queuing strategy init is required");
  }
  const value = Number(init.highWaterMark);
  if (!Number.isFinite(value) || value < 0) throw new RangeError("Invalid highWaterMark");
  return value;
