      const name = input.slice(index + 2, end).trim().split(/\s/u, 1)[0].toLowerCase();
      for (let depth = stack.length - 1; depth > 0; depth -= 1) {
        if (stackNames[depth] === name) {
          stack.length = depth;
          stackNames.length = depth;
          break;
