}

function syncEntries(record) {
  const snapshots = navigationEntriesSnapshot();
  const liveKeys = new Set(snapshots.map(entry => entry.key));
  for (const [key, object] of record.entriesByKey) {
    if (liveKeys.has(key)) continue;
