      record.entriesByKey.set(snapshot.key, object);
    }
    Object.assign(requireRecord(object), {
      key: snapshot.key,
      id: snapshot.id,
      url: snapshot.url,
      index: snapshot.index,
      entryState: snapshot.state,
    });
