  if (networkRequestRecorder === null) return;
  try {
    networkRequestRecorder.record({
      api,
      method: request.method,
      url: request.url,
      headers: [...headersEntries(request.headers)],
      body: request.bytes,
      outcome,
    });
  } catch {
    // Request observability must never change the page-visible network result.
  }
