    requireWritableTransaction(transaction);
    return scheduleStoreRequest(record, name, args, () => {
      record.metadata.records.clear();
      return undefined;
    });
  }
  if (name === "delete") {
    requireWritableTransaction(transaction);
    return scheduleStoreRequest(record, name, args, () => {
      deleteByQuery(record.metadata, args[0]);
      return undefined;
    });
  }
