  const value = Object.create(IDBIndex.prototype);
  state.set(value, {
    kind: "index",
    object: value,
    metadata,
    name: metadata.name,
    objectStore,
    keyPath: cloneMaybe(metadata.keyPath),
    multiEntry: metadata.multiEntry,
    unique: metadata.unique,
