  state.slotchangeQueued = true;
  queueMicrotask(() => {
    state.slotchangeQueued = false;
    for (const slot of slotsInShadowRoot(root)) {
      const assigned = assignedNodesForSlot(slot);
      const signature = assigned.slice();
