import { defineGlobalConstructor } from "../../webidl/descriptor.js";
import { registerNativeFunction } from "../../webidl/native-function.js";

export function MediaList() {
  throw new TypeError("Illegal constructor");
}
registerNativeFunction(MediaList, "MediaList");

export function installMediaListConstructor() {
  delete MediaList.prototype.constructor;
  defineGlobalConstructor("MediaList", MediaList);
}

import { traceGetter } from "../../trace/trace-accessor.js";
import { registerNativeFunction, registerNativeGetter } from "../../webidl/native-function.js";
import { requireMediaList } from "./media-list-state.js";

export function mediaListReadonlyDescriptor(name, read) {
  const descriptor = Object.getOwnPropertyDescriptor({
    get [name]() {
      const result = read(requireMediaList(this));
      traceGetter(`window.MediaList.prototype.${name}`, "MediaList", result);
      return result;
    },
  }, name);
  registerNativeGetter(descriptor.get, name);
  return descriptor;
}

export function mediaListAccessorDescriptor(name, read, write) {
  const descriptor = Object.getOwnPropertyDescriptor({
    get [name]() {
      const result = read(requireMediaList(this));
      traceGetter(`window.MediaList.prototype.${name}`, "MediaList", result);
      return result;
    },
    set [name](value) {
      requireMediaList(this);
      write(this, value);
    },
  }, name);
  registerNativeGetter(descriptor.get, name);
  registerNativeFunction(descriptor.set, `set ${name}`);
  return descriptor;
}

import { MediaList } from "./media-list-constructor.js";

const state = new WeakMap();

export function createMediaList(text = "") {
  const list = Object.create(MediaList.prototype);
  state.set(list, { values: parseMediaText(text), indexedLength: 0 });
  refreshMediaList(list);
  return list;
}

export function requireMediaList(value) {
  const record = state.get(value);
  if (record === undefined) throw new TypeError("Illegal invocation");
  return record;
}

export function setMediaText(list, text) {
  requireMediaList(list).values = parseMediaText(text);
  refreshMediaList(list);
}

export function refreshMediaList(list) {
  const record = requireMediaList(list);
  for (let index = record.values.length; index < record.indexedLength; index += 1) {
    delete list[index];
  }
  for (let index = 0; index < record.values.length; index += 1) {
    Object.defineProperty(list, index, {
      value: record.values[index],
      writable: false,
      enumerable: true,
      configurable: true,
    });
  }
  record.indexedLength = record.values.length;
}

function parseMediaText(text) {
  const values = [];
  for (const part of `${text}`.split(",")) {
    const value = part.trim();
    if (value !== "" && !values.includes(value)) values.push(value);
  }
  return values;
}

import { mediaListAccessorDescriptor } from "./media-list-property.js";
import { setMediaText } from "./media-list-state.js";
export const mediaText = mediaListAccessorDescriptor(
  "mediaText",
  record => record.values.join(", "),
  setMediaText,
);

import { mediaListMethod } from "./media-list-method.js";
import { refreshMediaList } from "./media-list-state.js";
export const appendMedium = mediaListMethod("appendMedium", 1, (record, args, list) => {
  const value = `${args[0]}`.trim();
  if (value !== "" && !record.values.includes(value)) record.values.push(value);
  refreshMediaList(list);
});

import { traceCall } from "../../trace/trace-function.js";
import { registerNativeFunction } from "../../webidl/native-function.js";
import { requireMediaList } from "./media-list-state.js";

export function mediaListMethod(name, arity, operation) {
  const callback = {
    [name](...args) {
      const result = operation(requireMediaList(this), args, this);
      traceCall(`window.MediaList.prototype.${name}`, "MediaList", args, result);
      return result;
    },
  }[name];
  Object.defineProperty(callback, "length", { value: arity, configurable: true });
  registerNativeFunction(callback, name);
  return callback;
}

import { mediaListMethod } from "./media-list-method.js";
import { refreshMediaList } from "./media-list-state.js";
export const deleteMedium = mediaListMethod("deleteMedium", 1, (record, args, list) => {
  const value = `${args[0]}`;
  const index = record.values.indexOf(value);
  if (index < 0) throw new DOMException("The medium was not found.", "NotFoundError");
  record.values.splice(index, 1);
  refreshMediaList(list);
});

