import { defineGlobalConstructor } from "../../webidl/descriptor.js";
import { registerNativeFunction } from "../../webidl/native-function.js";

export function SVGLengthList() { throw new TypeError("Illegal constructor"); }
export function SVGNumberList() { throw new TypeError("Illegal constructor"); }
export function SVGPointList() { throw new TypeError("Illegal constructor"); }
export function SVGStringList() { throw new TypeError("Illegal constructor"); }
export function SVGTransformList() { throw new TypeError("Illegal constructor"); }

for (const constructor of [
  SVGLengthList,
  SVGNumberList,
  SVGPointList,
  SVGStringList,
  SVGTransformList,
]) {
  registerNativeFunction(constructor, constructor.name);
}

export function installSVGListConstructors() {
  for (const constructor of [
    SVGLengthList,
    SVGNumberList,
    SVGPointList,
    SVGStringList,
    SVGTransformList,
  ]) {
    delete constructor.prototype.constructor;
    defineGlobalConstructor(constructor.name, constructor);
  }
}

import { traceCall } from "../../trace/trace-function.js";
import {
  registerNativeFunction,
  registerNativeGetter,
} from "../../webidl/native-function.js";
import {
  appendSVGListItem,
  clearSVGList,
  consolidateSVGTransformList,
  createTransformFromMatrix,
  getSVGListItem,
  initializeSVGList,
  insertSVGListItem,
  refreshSVGList,
  removeSVGListItem,
  replaceSVGListItem,
  requireSVGList,
} from "./svg-list-state.js";

export function createSVGListMembers(interfaceName, transform = false) {
  const members = {
    length: getter(interfaceName, "length", value => requireSVGList(value).values.length),
    numberOfItems: getter(
      interfaceName,
      "numberOfItems",
      value => requireSVGList(value).values.length,
    ),
    appendItem: method(interfaceName, "appendItem", 1, (value, args) =>
      appendSVGListItem(value, args[0])),
    clear: method(interfaceName, "clear", 0, value => clearSVGList(value)),
    getItem: method(interfaceName, "getItem", 1, (value, args) =>
      getSVGListItem(value, args[0])),
    initialize: method(interfaceName, "initialize", 1, (value, args) =>
      initializeSVGList(value, args[0])),
    insertItemBefore: method(interfaceName, "insertItemBefore", 2, (value, args) =>
      insertSVGListItem(value, args[0], args[1])),
    removeItem: method(interfaceName, "removeItem", 1, (value, args) =>
      removeSVGListItem(value, args[0])),
    replaceItem: method(interfaceName, "replaceItem", 2, (value, args) =>
      replaceSVGListItem(value, args[0], args[1])),
    values: method(interfaceName, "values", 0, value => refreshSVGList(value).values()),
  };
  if (transform) {
    members.consolidate = method(interfaceName, "consolidate", 0, value =>
      consolidateSVGTransformList(value));
    members.createSVGTransformFromMatrix = method(
      interfaceName,
      "createSVGTransformFromMatrix",
      1,
      (_value, args) => createTransformFromMatrix(args[0]),
    );
  }
  return members;
}

function getter(interfaceName, name, read) {
  const callback = function () {
    const result = read(this);
    traceCall(`window.${interfaceName}.prototype.${name}`, interfaceName, [], result);
    return result;
  };
  registerNativeGetter(callback, name);
  return callback;
}

function method(interfaceName, name, arity, operation) {
  const callback = {
    [name](...args) {
      requireSVGList(this);
      const result = operation(this, args);
      traceCall(`window.${interfaceName}.prototype.${name}`, interfaceName, args, result);
      return result;
    },
  }[name];
  Object.defineProperty(callback, "length", { value: arity, configurable: true });
  registerNativeFunction(callback, name);
  return callback;
}

import {
  SVGLengthList,
  SVGNumberList,
  SVGPointList,
  SVGStringList,
  SVGTransformList,
} from "./svg-list-constructors.js";
import {
  createSVGMatrix,
  createSVGTransform,
  matrixValues,
  multiplySVGMatrix,
  requireSVGValue,
} from "./svg-value-state.js";

const state = new WeakMap();
const definitions = {
  length: [SVGLengthList, "length"],
  number: [SVGNumberList, "number"],
  point: [SVGPointList, "point"],
  string: [SVGStringList, null],
  transform: [SVGTransformList, "transform"],
};

export function createSVGList(kind, initial = []) {
  const definition = definitions[kind];
  if (definition === undefined) throw new TypeError("Unknown SVG list kind");
  const list = Object.create(definition[0].prototype);
  const record = { kind, values: [], indexedLength: 0 };
  state.set(list, record);
  record.values.push(...[...initial].map(value => normalizeItem(record, value)));
  refreshSVGList(list);
  return list;
}

export function requireSVGList(value, kind) {
  const record = state.get(value);
  if (record === undefined || (kind !== undefined && record.kind !== kind)) {
    throw new TypeError("Illegal invocation");
  }
  return record;
}

export function refreshSVGList(list) {
  const record = requireSVGList(list);
  for (let index = record.values.length; index < record.indexedLength; index += 1) {
    delete list[index];
  }
  for (let index = 0; index < record.values.length; index += 1) {
    Object.defineProperty(list, index, {
      value: record.values[index],
      writable: false,
      enumerable: true,
      configurable: true,
    });
  }
  record.indexedLength = record.values.length;
  return record.values;
}

export function appendSVGListItem(list, value) {
  const record = requireSVGList(list);
  const item = normalizeItem(record, value);
  record.values.push(item);
  refreshSVGList(list);
  return item;
}

export function clearSVGList(list) {
  requireSVGList(list).values.splice(0);
  refreshSVGList(list);
}

export function getSVGListItem(list, index) {
  const record = requireSVGList(list);
  const normalized = Number(index) >>> 0;
  if (normalized >= record.values.length) throw indexError();
  return record.values[normalized];
}

export function initializeSVGList(list, value) {
  const record = requireSVGList(list);
  const item = normalizeItem(record, value);
  record.values.splice(0, record.values.length, item);
  refreshSVGList(list);
  return item;
}

export function insertSVGListItem(list, value, index) {
  const record = requireSVGList(list);
  const item = normalizeItem(record, value);
  const normalized = Math.min(Number(index) >>> 0, record.values.length);
  record.values.splice(normalized, 0, item);
  refreshSVGList(list);
  return item;
}

export function removeSVGListItem(list, index) {
  const record = requireSVGList(list);
  const normalized = Number(index) >>> 0;
  if (normalized >= record.values.length) throw indexError();
  const [item] = record.values.splice(normalized, 1);
  refreshSVGList(list);
  return item;
}

export function replaceSVGListItem(list, value, index) {
  const record = requireSVGList(list);
  const normalized = Number(index) >>> 0;
  if (normalized >= record.values.length) throw indexError();
  const item = normalizeItem(record, value);
  record.values[normalized] = item;
  refreshSVGList(list);
  return item;
}

export function consolidateSVGTransformList(list) {
  const record = requireSVGList(list, "transform");
  if (record.values.length === 0) return null;
  let matrix = createSVGMatrix();
  for (const transform of record.values) {
    matrix = multiplySVGMatrix(matrix, requireSVGValue(transform, "transform").matrix);
  }
  const consolidated = createSVGTransform(matrix);
  record.values.splice(0, record.values.length, consolidated);
  refreshSVGList(list);
  return consolidated;
}

export function createTransformFromMatrix(matrix) {
  matrixValues(matrix);
  return createSVGTransform(matrix);
}

function normalizeItem(record, value) {
  if (record.kind === "string") return `${value}`;
  requireSVGValue(value, definitions[record.kind][1]);
  return value;
}

function indexError() {
  return new DOMException("The index is not in the allowed range.", "IndexSizeError");
}

