import { traceCall } from "../../trace/trace-function.js";
import { registerNativeFunction } from "../../webidl/native-function.js";
import {
  setTokens,
  tokensOf,
  validateToken,
} from "./dom-token-list-state.js";

export const add = {
  add(...values) {
    const additions = values.map(validateToken);
    const tokens = tokensOf(this);
    for (const token of additions) {
      if (!tokens.includes(token)) {
        tokens.push(token);
      }
    }
    setTokens(this, tokens);
    traceCall("window.DOMTokenList.prototype.add", "DOMTokenList", values, undefined);
  },
}.add;
registerNativeFunction(add, "add");

import { traceCall } from "../../trace/trace-function.js";
import { registerNativeFunction } from "../../webidl/native-function.js";
import { tokensOf, validateToken } from "./dom-token-list-state.js";

export const contains = {
  contains(value) {
    const token = validateToken(value);
    const result = tokensOf(this).includes(token);
    traceCall("window.DOMTokenList.prototype.contains", "DOMTokenList", [value], result);
    return result;
  },
}.contains;
registerNativeFunction(contains, "contains");

import { traceCall } from "../../trace/trace-function.js";
import { registerNativeFunction } from "../../webidl/native-function.js";
import { refreshDOMTokenList } from "./dom-token-list-state.js";

export const entries = {
  entries() {
    const result = refreshDOMTokenList(this).entries();
    traceCall("window.DOMTokenList.prototype.entries", "DOMTokenList", [], result);
    return result;
  },
