  for (const child of requireNode(parent).children) {
    const accepted = acceptNode(state, child);
    if (accepted === FILTER_ACCEPT) {
      return child;
    }
    if (accepted !== FILTER_REJECT) {
      const nested = firstVisibleDescendant(state, child);
      if (nested !== null) {
        return nested;
      }
    }
  }
  return null;
}

