  const bit = 1 << (requireNode(node).nodeType - 1);
  if ((state.whatToShow & bit) === 0) {
    return FILTER_SKIP;
  }
  const filter = state.filter;
  if (filter === null) {
    return FILTER_ACCEPT;
  }
  if (state.active) {
    throw new DOMException(
      "The traversal filter is already active.",
      "InvalidStateError",
    );
  }
  state.active = true;
