    result = typeof filter === "function"
      ? filter(node)
      : filter.acceptNode(node);
  } finally {
    state.active = false;
  }
  const normalized = Number(result) >>> 0;
  return normalized === FILTER_REJECT || normalized === FILTER_SKIP
    ? normalized
    : FILTER_ACCEPT;
