} from "../../../webidl/native-function.js";
import {
  traceGetter,
  traceSetter,
} from "../../../trace/trace-accessor.js";
import {
  getWindowEventHandler,
  setWindowEventHandler,
} from "../window-event-handler-state.js";

const descriptor = Object.getOwnPropertyDescriptor({
  get onabort() {
    const value = getWindowEventHandler("onabort");
    traceGetter("window.onabort", "Window", value);
    return value;
  },
  set onabort(value) {
    setWindowEventHandler("onabort", value);
    traceSetter("window.onabort", "Window", value);
  },
}, "onabort");

export function installOnabortGlobal() {
  registerNativeGetter(descriptor.get, "onabort");
  registerNativeFunction(descriptor.set, "set onabort");
  Object.defineProperty(globalThis, "onabort", {
    get: descriptor.get,
    set: descriptor.set,
    enumerable: true,
    configurable: true,
  });
}

import { withWindowEvent } from "./window-state-globals-runtime.js";

const handlers = new Map();
const listeners = new Map();

export function getWindowEventHandler(name) {
  return handlers.get(name) ?? null;
}

export function setWindowEventHandler(name, value) {
  const type = name.slice(2);
  const previous = listeners.get(name);
  if (previous !== undefined) {
    globalThis.removeEventListener(type, previous);
    listeners.delete(name);
  }
  if (!isEventHandler(value)) {
    handlers.delete(name);
    return;
  }
  handlers.set(name, value);
  const listener = event => withWindowEvent(event, () => {
    if (typeof value === "function") {
      return Reflect.apply(value, globalThis, [event]);
    }
    return Reflect.apply(value.handleEvent, value, [event]);
  });
  listeners.set(name, listener);
  globalThis.addEventListener(type, listener);
}

function isEventHandler(value) {
  return typeof value === "function"
    || (
      value !== null
      && typeof value === "object"
      && typeof value.handleEvent === "function"
    );
}

