    closed: {
      get() { return requireVirtualWindow(this).closed; },
      enumerable: true,
      configurable: true,
    },
    name: {
      get() { return requireVirtualWindow(this).name; },
      set(value) { requireVirtualWindow(this).name = `${value}`; },
      enumerable: true,
      configurable: true,
    },
    location: {
      get() { return requireVirtualWindow(this).url; },
      enumerable: true,
      configurable: true,
    },
