function decodeStringList(encoded) {
  const output = [];
  let index = 0;
  while (index < encoded.length) {
    const colon = encoded.indexOf(":", index);
    if (colon < 0) break;
    const length = Number(encoded.slice(index, colon));
    const start = colon + 1;
    output.push(encoded.slice(start, start + length));
    index = start + length;
  }
  return output;
}

